$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_41ec178892052759edfd515ae5c74d67'] = 'Als Standardgruppe verwenden';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5b7417c1bd6f4e8a1181f2e7295a3e28'] = 'Mit dieser Option können Sie die Gruppe als Standardkundengruppe zuweisen. Die Standardkundengruppe wird in Bezug auf die letzte vom Kunden hinzugefügte Adresse konfiguriert.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ab2004936572b7bcf164741f383f4c97'] = 'Standardgruppe mit Adresse ändern';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_307181015f28b24b5cf56a56f268fefc'] = 'Mit dieser Option können Sie die dem Land zugeordnete Kundenstandardgruppe in diesem Abschnitt ändern, wenn der Kunde eine Standardadresse auswählt oder während des Kaufvorgangs. Wenn die ausgewählte Adresse keine gültige Umsatzsteuer-Identifikationsnummer hat, wechselt das System zur Prestashop-Kundenstandardgruppe';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f008d6b21c614caada820eac4e9ae732'] = 'Kunden aus anderen Gruppen entfernen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_48cade9acdfa67cc5014f8e885463462'] = 'Diese Option entfernt den Client aus den Gruppen, denen er zuvor zugewiesen war, und lässt ihn nur der Gruppe zugewiesen, die in diesem Abschnitt nach Land konfiguriert wurde. Die Standardgruppe wird in die aktuell zugewiesene Gruppe geändert.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1ccca8b7e16706b70eb3862d8cac1cf3'] = 'Aktivierungseinstellungen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5c421a5582c9affbd59ce0fbe57a4060'] = 'EU-Länder sind standardmäßig ausgewählt. Die Option [Countries for validation] ist nur nützlich, um Länder hinzuzufügen oder zu entfernen, die zur Europäischen Union gehören oder eine Vereinbarung mit innergemeinschaftlichen Operationen haben. In einer normalen Situation ist diese Option vordefiniert und sollte nicht geändert werden. Beachten Sie, dass Nordirland für innergemeinschaftliche Operationen eingeschlossen ist und zum Vereinigten Königreich (England) gehört.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1a7c23373b408af50cb839fbe7d52c85'] = 'Backoffice-Validierung';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_882cb664782409edd93fd5d3ab85efec'] = 'Aktivieren Sie die Validierung für Umsatzsteuer-Identifikationsnummern im Adressbereich des Backoffice.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_50da52ae50ce1c69d9ec84f9ae7de0e1'] = 'Einige Module verwenden Controller des Backoffice für die Erstellung von Kundenadressen durch Crontasks oder durch Prozesse. Damit das Modul die UID-Nummern dieser angelegten Adressen validieren kann, muss diese Option aktiviert werden.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_bb7bd05d489b31a0c31edfd4897745f4'] = 'Front-Office-Validierung';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9176ffc4cac7d0b19daba445c764c2b1'] = 'Aktivieren Sie die Validierung für Umsatzsteuer-Identifikationsnummern im Adressbereich des Front-Office, wenn ein Kunde eine Adresse erstellt oder ändert oder während des Bestellvorgangs.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_32b4427fd2b69a2c80d21c213e50f974'] = 'Länder für die Validierung';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f173aae292b6e3a5365cb4ac449d60b5'] = 'Wählen Sie die Länder aus, um die Validierung zu aktivieren. Sie sollten diese Liste nicht ändern, es sei denn, die Vorschriften für den innergemeinschaftlichen Betrieb ändern sich und die beteiligten Länder werden geändert.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_2d59f051b72e3fab1863a7720267abf8'] = 'STRG und klicken oder klicken und ziehen, um mehrere Optionen auszuwählen.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c9cc8cce247e49bae79f15173ce97354'] = 'Speichern';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b51d6159f43c28990c668ee0f5722e68'] = 'Beachten Sie, dass für eine rechtsgültige Steuerbefreiung neben dem Kunden auch der Händler mit gültiger innergemeinschaftlicher Umsatzsteuer registriert sein muss. Das System validiert die innergemeinschaftliche Umsatzsteuer-Identifikationsnummer des Händlers durch VIES oder GOV.UK, bevor es in der Datenbank gespeichert wird.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_4c4974ffdbc418a104b9ac8fe50329f2'] = 'Händler MwSt';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6c5e748d9e2d43bffbcf34fba6bf83c8'] = 'Geben Sie die Umsatzsteuer-Identifikationsnummer (mit ISO-Code) des Unternehmens ein, mit der das Unternehmen für innergemeinschaftliche Geschäfte registriert ist. Schreiben Sie die vollständige Nummer mit ISO-Code (Bsp.: FR17852960). Umsatzsteuernummern aus dem Vereinigten Königreich sind nicht zulässig.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1709b640f134a404881e88edc01258bc'] = 'Dies ist für die 2-Wege-Validierungssystemoption erforderlich. Kann leer bleiben, wenn Sie kein 2-Wege-Validierungssystem verwenden.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d927b3b03a13bf31b7eb8f6ff92e07ca'] = 'Warnmeldung in Adresse anzeigen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8c0a80538a54ae2b99f5d930b34f65e2'] = 'Zeigt Warnmeldungen im Adressbereich des Kundenkontos an, wenn sie keine gültige Umsatzsteuer-Identifikationsnummer registriert haben oder eine Umsatzsteuer-Identifikationsnummer registrieren müssen (Pflichtfeldoption aktiviert) oder das Firmenfeld validieren müssen (Firmenvalidierungsoption aktiviert).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6bf5595b28f11a3701d3dc6c9d6e449d'] = 'Funktioniert nur in Prestashop 1.7 oder höher';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e119406d93b7385c70d4b607a81bcf32'] = 'Checkout nicht zulassen, wenn die Adresse unvollständig ist';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_a2f3bd6da6361f19d81c48c65446422f'] = 'Diese Option erlaubt dem Kunden nicht, mit dem Kaufvorgang fortzufahren, wenn die ausgewählte Adresse das Feld für die Umsatzsteuer-Identifikationsnummer oder den Firmennamen enthält, das validiert oder ausgefüllt werden muss (abhängig von den ausgewählten Validierungs- und Umsatzsteuerfeld-Konfigurationsoptionen). Nützliche Option für Kunden, die bereits Adressen in der Datenbank registriert hatten';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d2afdcacd59b06e5541e4c32b24581b7'] = 'Benutzerdefinierter Preisblock';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6607b1376017ff8c5845ae0e911f962b'] = 'Fügen Sie einen benutzerdefinierten Text im Produktpreisblock (unter dem Preis) hinzu und er wird angezeigt, wenn ein Kunde eine Adresse mit gültiger Umsatzsteuer-Identifikationsnummer ausgewählt hat und steuerbefreit ist.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1b94355921381017449e017baaa43e5e'] = 'Es wird dringend empfohlen, das 2-Wege-Validierungssystem zu verwenden, um die rechtliche Integrität der Steuerbefreiung bei innergemeinschaftlichen Transaktionen sicherzustellen und sowohl die Umsatzsteuer-Identifikationsnummer des Händlers als auch die des Kunden zu überprüfen. Für die 2-Wege-Validierung ist es notwendig, die Umsatzsteuer-Identifikationsnummer des Händlers in den allgemeinen Einstellungen festzulegen. Wenn die Option Merchant vat leer ist, verwendet das System in jedem Fall die 1-Wege-Validierung.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8dd10878b69a18f881af0c0e36247cb0'] = 'Validierungssystem';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_24b0f41249450fb2b8d43025022f44a8'] = 'Wählen Sie das Validierungssystem für die Umsatzsteuer-Identifikationsnummer aus. Die 1-Wege-Validierung prüft und validiert nur die Umsatzsteuer-Identifikationsnummer des Kunden, auch wenn der Händler keine gültige Umsatzsteuer-Identifikationsnummer hat. Die Zwei-Wege-Validierung sendet Informationen zur Umsatzsteuer-Identifikationsnummer des Händlers und zur Umsatzsteuer-Identifikationsnummer des Kunden und überprüft, ob beide bereits für innergemeinschaftliche Transaktionen mit Steuerbefreiung registriert sind.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6c106d4c676d2f70ee14fe9ac8b53a99'] = 'Funktioniert nur, wenn die Validierungssystemoption [Format + API system] ausgewählt ist.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_147dc6e7f6af2b9b3bb0cf77bab90e41'] = 'Validierung 1-Weg';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_4792ea7be8342c48e29cf2eeae895962'] = 'Validierung 2-Wege';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_29dcf8f9e61af7c1f9e4bbd16cf4f2cf'] = 'Validierungsmodus';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c5a4695fbfd74fcfac2a3d505c66d43b'] = 'Diese Option legt den Modus der MwSt.-Validierung fest. Der strenge Modus validiert Umsatzsteuer-Identifikationsnummern mit dem richtigen Format, das vom Kunden eingefügt wurde (z. B.: FR01609493). Der Smart-Modus validiert MwSt.-Nummern, auch wenn das Format vom Kunden nicht korrekt eingegeben wurde (Bsp.: FR-01609493, FR 01609493, FR01.609.493) und als gültiges Format gespeichert (Bsp.: FR01609493)';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_006576df800107db40832e2e0fd44931'] = 'Strikter Modus';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_dfea54ef85aa32f8489ae0f672d91c5a'] = 'Smart-Modus';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_94b93271d0dfce2b59ba77cc690415a3'] = 'Validierungstyp';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_99dd2d580dc5196d7e919645a054c28a'] = 'Diese Option legt die Art der MwSt.-Validierung fest. Der Formatvalidierungsmodus validiert nur das Format der MwSt.-Nummer (Bsp.: FR01609493). Format + API-Validierung validiert das MwSt.-Nummernformat und verifiziert es im VIES- oder GOV.UK-API-System (empfohlen für MwSt.-Befreiung).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5718f767fd5edcc521f57c23f4527725'] = 'Formatvalidierung';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_3b19c288b70dc9b277b83cb937d1df74'] = 'Format + API-Systemvalidierung';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_54df18253716c9795f66ed2d4255833b'] = 'Unternehmensvalidierung';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_93370977d5f528ed94a8f7cf6e7156be'] = 'Wenn es aktiviert ist, wird das Feld für den Firmennamen zusammen mit den vom VIES/GOV.UK-System erhaltenen Informationen zur Umsatzsteuer-Identifikationsnummer validiert. Wenn der Kunde den Firmennamen nicht genau so eingibt, wie er in der Systemdatenbank von VIES/GOV.UK erscheint, wird die Adresse nicht mit dieser Umsatzsteuer-Identifikationsnummer validiert. Die in der Datenbank registrierten früheren Kunden mit noch nicht validiertem Firmennamen, aber gültiger Mehrwertsteuer, müssen die Adressinformationen aktualisieren, bevor sie einen Kauf im Geschäft tätigen.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ac50ccc149ebb161e8d8d19c3a6a946f'] = 'Um Fehler in den Adressformularen zu vermeiden, achten Sie darauf, dass das Feld „Firma“ im Formular angezeigt wird. Wenn diese Option aktiviert ist, wird dieses Feld im Adressformular benötigt.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_71e56d83a626d8268caf28e8eac3d64a'] = 'Firmennamen automatisch einfügen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_52800a2170bf04b8329ec097aa422d63'] = 'Wenn diese Option aktiviert ist und der Kunde eine Adresse mit einer gültigen Umsatzsteuer-Identifikationsnummer registriert, fügt das System den registrierten Firmennamen aus dem VIES- oder GOV.UK-System ein. Hat der Kunde im Firmenfeld einen anderen Firmennamen eingetragen, wird dieser mit dem im System registrierten korrekten Namen überschrieben.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_be496e62d1ca3007170567553e8441c0'] = 'Diese Option ist nicht mit der aktivierten Option [Company validation] kompatibel.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_de333ce299100de1723bb0d246f8845e'] = 'Doppelte Mehrwertsteuer zulassen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5c5c48e6b16c9c8e7d5f2924dba18076'] = 'Diese Option aktivieren oder deaktivieren, um unterschiedliche Kundenregistrierungen mit denselben Umsatzsteuernummern zuzulassen.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_73e32e03f4ab7374222b68de7f97a2b6'] = 'Skip-API-System fehlgeschlagen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9f5f6676c393f344b028ba9c4e77159f'] = 'Diese Option überspringt die Validierung, falls das VIES/GOV.UK-API-System während des Validierungsprozesses fehlschlägt. Der Kunde kann mit der Adressregistrierung und dem Checkout fortfahren. Die Umsatzsteuer-Identifikationsnummer erscheint als [Validated] und der Systemstatus wird in roter Farbe als [API request processing error] in der Umsatzsteuerverwaltungsliste angezeigt.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c65e5a2319190e3346c5ac53ad702b2b'] = 'Diese Option funktioniert nur in der API-Systemvalidierung.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d337d426b6c49df575234f8e7a001736'] = 'Speichern Sie in Großbuchstaben';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1ca36376b1a467f9f5c8f2fca7614721'] = 'Aktivieren Sie diese Option, um die Umsatzsteuer-Identifikationsnummer mit Großbuchstaben zu speichern, wenn der Kunde Aktionen zum Hinzufügen oder Aktualisieren im Adressformular ausführt. Beispiel: FR01609493 statt fr01609493';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_85fffe8f5074d606fa202fa5ae90d8bb'] = 'Schwarze Liste';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_a9fc6209ac169e499232af8c573ce560'] = 'Setzen Sie Mehrwertsteuernummern in eine schwarze Liste, um die Kundenregistrierung mit einigen dieser Nummern nicht zuzulassen. Schreiben Sie eins nach dem anderen durch Komma getrennt.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_7b13005d0082f3a02ff758d17debf5ad'] = 'Das Modul fügt den in diesem Abschnitt konfigurierten Status ein, wenn der Kunde eine Bestellung aufgibt. Beim Bestellstatus mit gültiger Umsatzsteuer-Identifikationsnummer wird diese zuerst eingefügt und unmittelbar danach der nächste Status, abhängig von den im Kaufprozess gewählten Zahlungsoptionen. Im Falle des Status der Bestellung mit ausstehender Umsatzsteuer-Identifikationsnummer aufgrund eines API-Prozessfehlers wird dieser als letzter und aktueller Status der Bestellung eingefügt, damit der Kunde weiß, dass seine Bestellung mit ausstehender Umsatzsteuer-Identifikationsnummer validiert wird.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c2f6f7927f37822c3b597d3686a44e70'] = 'Bestellstatus, wenn die Mehrwertsteuer validiert ist';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5253f1fadf04ee3358f139e6040e1c80'] = 'Diese Option konfiguriert den Status der Bestellung, wenn die Umsatzsteuer-Identifikationsnummer erfolgreich validiert wurde. Dieser Status wird am Anfang angezeigt, direkt vor dem Standardstatus bei der Bestellung. Stellen Sie [Disable] ein, um die Option zu deaktivieren';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8a3ad48e7c2d0aa8fb38c2c03d13224a'] = 'Das Modul hat einen eigenen Status namens \"Umsatzsteuernummer validiert\" erstellt. Sie können jedoch jeden benutzerdefinierten Status verwenden.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f735ac75c9a297e148d80eff382ebe4b'] = 'Auftragsstatus bei Ausfall des API-Systems';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d63a96b35bf6c72b9c138d0881421604'] = 'Diese Option konfiguriert den Status der Bestellung, wenn das API-System die Umsatzsteuer-Identifikationsnummer des Kunden nicht validieren konnte, wenn die Option [Skip validation] aktiviert wurde und der Kunde mit der Bestellung fortfahren konnte. Stellen Sie [Disable] ein, um die Option zu deaktivieren';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_833f65cc3fe8b58eb450caf32d51f3a9'] = 'Das Modul hat einen eigenen Zustand mit dem Namen „Umsatzsteuer-Identifikationsnummer ausstehend“ erstellt. Sie können jedoch jeden benutzerdefinierten Status verwenden.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_a81e07c3a2421768b9ee85c7c5e9df76'] = 'Kundengruppenzuordnung nach Land';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d850ba42b3ce90ace18bc59069f47c27'] = 'Das System wird mit der Validierung aller vom Kunden erstellten Adressen fortfahren, solange sie die Bedingungen für die Validierung erfüllen, unabhängig davon, ob der Adresstyp in der in diesem Abschnitt gezeigten Option ausgewählt wurde. Diese Option dient nur dazu, zu bestimmen, ob der Kunde bei der Auswahl der Adresse im Checkout-Prozess steuerbefreit ist.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_66c36b9d18dd144a80435ebffd4b7ac1'] = 'Mehrwertsteuerbefreiung';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8cb88c12dc7c0a45a4e0bea3050bd233'] = 'Mit dieser Option können Sie Steuern von Kunden mit einer gültigen Umsatzsteuer-Identifikationsnummer entfernen. Funktioniert für jede Art von Validierung (Format oder API-System).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_bd5bece1f53fae4660f7673d3f1f00bd'] = 'Die Preise der Produkte und die Beträge des Warenkorbs werden ohne Steuern angezeigt.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_0f35945c0ec8ece14d52e5fb9fdb6572'] = 'Adresstyp';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b85bee80d4cfb438d11cd19f63f7099f'] = 'Mit dieser Option können Sie Steuern von Kunden mit einer gültigen Umsatzsteuer-Identifikationsnummer in einem bestimmten Adresstyp (Lieferadresse, Rechnungsadresse oder beides) entfernen.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_042d32665de5a16cbbe0aeb373948f60'] = 'Bei Auswahl der Option „Rechnungsadresse und Lieferadresse“ erfolgt eine Steuerbefreiung, wenn eine der beiden Adressen oder beide eine gültige Umsatzsteuer-Identifikationsnummer haben.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_601d8c4b9f72fc1862013c19b677a499'] = 'Rechnungsanschrift';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_af0f5bdc5be121b9307687aeeae38c17'] = 'Lieferadresse';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ab330c76d81d3f96fb7d97d179c82bc7'] = 'Rechnungs- und Lieferadresse';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_09966285b248320d88be53355b466f21'] = 'Lokales Land';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_89a0979cda66d6e96fd0c7a12b9f8709'] = 'Mit dieser Option können Sie Ihr lokales Land zuweisen, in dem Produktpreise und Bestellungen immer für dieses Land besteuert werden.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_41699887750c4faa22a2103e0db81c20'] = 'Ausnahme von Kundengruppen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b7d4d2cadf4db0aaab3bee7348154fd3'] = 'Mit dieser Option können Sie Steuern für bestimmte Kundengruppen entfernen, auch wenn die Umsatzsteuer-Identifikationsnummer gültig ist oder nicht. Leer lassen, um es für alle Kundengruppen zu deaktivieren. Wenn Sie eine beliebige Gruppe ankreuzen, wird die Steuerbefreiung nur für Kunden ausgewählter Gruppen angewendet. Diese Option ist völlig unabhängig von der Option [VAT exemption] .';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_0a365a829e2aecdb84fc372153aac60d'] = 'Rechtstext der Rechnung';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8b006b1a87879287f5c7c0a382857d01'] = 'Fügen Sie den Rechtstext in der Rechnung einer mehrwertsteuerbefreiten Bestellung hinzu. Der Text wird unten zum standardmäßigen Rechtstext hinzugefügt.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_93f39badf1dd476bc3465e2366f91210'] = 'Rechnungshinweis';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_981bee80cb84e3422fe8e0de8d0694df'] = 'Fügen Sie eine Notiz in der Rechnung von einer Bestellung mit Mehrwertsteuerbefreiung hinzu. Der Text wird oben zu hinzugefügten Notizen hinzugefügt.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_fe7fe004668ea7015c4ccc584dbafcca'] = 'Diese Optionen werden nur für Länder angewendet, die auf der Registerkarte [Activation] zur Validierung ausgewählt wurden.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f028f32e19d6c84ce3238a20459f6d42'] = 'HINWEIS: Diese Optionen werden bei der Validierung von MwSt.-Nummern aus dem Backoffice nicht angewendet.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_45c78c1b74b189ac8a5adc5b8e7a46c5'] = 'Nur die Checkout-Module, die wir zu 100 % integriert haben, sind mit den Optionen in diesem Abschnitt kompatibel. Einige dieser Optionen funktionieren möglicherweise nicht mit anderen Checkout-Modulen, auch nicht mit denen, die von diesem Modul unterstützt werden und die wir in der Kompatibilitätsliste erwähnen. Dies liegt daran, dass die Module, die die Checkout-Seite verwalten, im Allgemeinen ihre eigenen Optionen und Controller verwenden, um die Felder zu verwalten, die im Checkout-Prozess ihres Moduls angezeigt werden.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_221094f1579a69ea1aed37744bc540f2'] = 'Mehrwertsteuerfeld';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_fc268a0f6d8150b1c6881adb0014e3c6'] = 'Wählen Sie diese Option aus, um das Feld in optional oder erforderlich umzuwandeln.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_d6dc27fada47cb77f2dca329eacdbedc'] = 'Diese Option funktioniert nur für Länder, die für die Validierung ausgewählt wurden.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e88e5e7b543453f0685b3b3593db4f9d'] = 'Optionales Feld';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_19f823c6453c2b1ffd09cb715214813d'] = 'Pflichtfeld';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_6b8c4fd358a49601a93e161d47a1b054'] = 'Anzeige nur für Unternehmen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5a777cce9211514bfadce87220ed49ab'] = 'Aktivieren Sie diese Option, um das Feld MwSt.-Nummer nur dann anzuzeigen, wenn Kunden einen Firmennamen eingeben. Blenden Sie das Feld Umsatzsteuer-Identifikationsnummer aus, wenn kein Firmenname vorhanden ist, und obwohl Sie dieses Feld als erforderlich auswählen, wird es zu einem optionalen Feld.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c0e292ad508997ec1c2a15d772cb128f'] = 'Diese Option funktioniert nur im Front Office. Das Firmenfeld wird in Adressform, aber in jedem Fall im Backoffice angezeigt.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b021df6aac4654c454f46c77646e745f'] = 'Etikett';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_fbf1481544354c8de9e4f2fd5daff40d'] = 'Passen Sie die Feldbeschriftung für die Umsatzsteuer-Identifikationsnummer an. Für Standardlabel leer lassen.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9b27e12d584b3438e811533b32e026e8'] = 'Legende';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ad07132b12ffdc38b5d7ef9859d98e0b'] = 'Passen Sie die Feldlegende der Umsatzsteuer-Identifikationsnummer an. Es befindet sich unterhalb des Eingangs. Für Standardlabel leer lassen.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f32f5ac2269b031043e213c23b4028eb'] = 'Der Betrag von %s ist der Schwellenwert für die Mehrwertsteuerbefreiung in britischen Mehrwertsteuernummern. Der Wechselkurs sollte regelmäßig per CRON-Task oder im Währungsbereich aktualisiert werden.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_891cc5630f27487cbe9b32bce8a7a45a'] = 'Brexit';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9e2c3b66dc9c2c79111a8d11d9e9c332'] = 'Aktive Brexit-Steuerregeln für Exporte in das Vereinigte Königreich.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_469dc620989561ab9ca079454545bb1e'] = 'Umsatzsteuerbefreiung in Unternehmen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_53593000054652057f05c7ef687ba3e6'] = 'Diese Option ermöglicht eine Mehrwertsteuerbefreiung für Unternehmen mit einer gültigen britischen Umsatzsteuer-Identifikationsnummer, wenn der Gesamtbetrag der Produkte im Warenkorb 135 GBP oder weniger beträgt';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9b35e882da84307a7d230265e0577da0'] = 'Bestellungen nicht zulassen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_ddeb8f4307f430983d53cb41b34474e1'] = 'Mit dieser Option können Sie wählen, ob Sie keine Käufe von Beträgen unter 135 GBP oder über 135 GBP zulassen möchten.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8276092a35ba53068c987f7d7072809e'] = 'Über 135 GBP';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_539064c25c9433e56c0fae15fe794306'] = 'Unter 135 GBP';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_25b74a3fe7cc70e18e584e84d87875fa'] = 'E-mailadressen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_2b50033cc81272b6fb76594eaf7bdb0f'] = 'Sie können verschiedene E-Mail-Adressen festlegen, um E-Mails von diesem Modul zu erhalten. Sie müssen eine korrekte E-Mail-Adresse angeben. Bei mehreren Adressen müssen Sie diese durch Kommas getrennt schreiben (Beispiel: test@test.com,test2@test2.com...).';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e2d81b28527e0dea0a247c058f5b2897'] = 'API-Benachrichtigungs-E-Mail';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_e1e436bcf0f1584ab270e8d6e0662f55'] = 'Senden Sie eine E-Mail-Benachrichtigung, wenn der Kunde registriert ist und die Mehrwertsteuervalidierung durch das API-System fehlschlägt.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_242263e7b06b99d29a69bc72407b9696'] = 'Senden Sie eine E-Mail an den Client, wenn die API fehlschlägt';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_1ca58cd422878a1b1ae81aee7fb02fce'] = 'Senden Sie dem Kunden eine E-Mail mit der Benachrichtigung, dass der Status der Bestellung aussteht, um die Umsatzsteuer-Identifikationsnummer zu validieren, wenn Sie eine Bestellung mit einer Adresse aufgeben, an der die Umsatzsteuer-Identifikationsnummer aufgrund eines API-Systemfehlers nicht validiert werden konnte und die Option [Skip validation] hat wurde im Abschnitt Validierungseinstellungen aktiviert, sodass der Kunde mit der Registrierung der Adresse und der Bestellung fortfahren kann.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_16a607f72b9d08637169d3047b33e7b8'] = 'Kundenbestätigungs-E-Mail';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8e1d4cca72fb64311138e83a894aacd9'] = 'Senden Sie eine E-Mail-Benachrichtigung, wenn der Kunde registriert ist und die Mehrwertsteuervalidierung durch das API-System erfolgreich durchgeführt wurde.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_5be5f2a68a48c39d9c42b8a5fc2fbd17'] = 'CRON-Einstellungen zur Überprüfung der Umsatzsteuer-Identifikationsnummern';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_b03b2f8739ada5eabe2ad2385370c659'] = 'Scanvorgang ab der zuletzt gescannten Adresse fortsetzen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_cd1a0229c38b3d47018619a1d1dddcc5'] = 'Diese Option muss aktiviert werden, wenn Sie möchten, dass das System mit dem Scannen ab der zuletzt gescannten Adresse fortfährt. Dies ist nützlich, wenn der letzte Scanvorgang fehlgeschlagen ist oder wenn Sie nicht möchten, dass das System erneut von der ersten in der Datenbank gespeicherten Adresse scannt.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_f8e69246c2f0444c12a03bdf5ffa39bf'] = 'Diese Option überspringt die Validierung, falls das VIES/GOV.UK-API-System während des Validierungsprozesses fehlschlägt. Die Umsatzsteuer-Identifikationsnummer erscheint als [Validated] und der Systemstatus wird in roter Farbe als [API request processing error] in der Umsatzsteuerverwaltungsliste angezeigt.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_280ec81039b065382dd5173775fd82af'] = 'Leere Umsatzsteuer-Identifikationsnummer löschen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_0e85114a80f3d5c50a737e4388acba5a'] = 'Kundenadresse mit leerer Umsatzsteuernummer löschen, falls das Feld erforderlich ist.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_c023f4c4cd6f1ae43c66e7bfc2ab5b7f'] = 'Ungültige Umsatzsteuer-Identifikationsnummer löschen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_3b12cad72a132bbb387855f5d4589cbd'] = 'Kundenadresse mit ungültiger Umsatzsteuer-Identifikationsnummer löschen.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_183b6fcaa152f5846e34c6695cfb4e51'] = 'Doppelte Umsatzsteuer-Identifikationsnummer löschen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_754d8064fd8e110027273abe06c49ed4'] = 'Kundenadresse mit doppelter Umsatzsteuer-Identifikationsnummer löschen. Das System lässt nur die erste erstellte Adresse und löscht den Rest mit doppelter Mehrwertsteuernummer, wenn doppelte Mehrwertsteuer nicht zulässig ist.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8b8c92abfa0d133ef1360066ef84c6e5'] = 'E-Mail für ungültige Umsatzsteuer-Identifikationsnummer senden';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8aeb24b94406f0b9129d888662714871'] = 'Sendet E-Mail an Kunden mit ungültiger Umsatzsteuer-Identifikationsnummer.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_a58c4772e7315f0a3bc629b73dac46c0'] = 'E-Mail für leere Umsatzsteuer-Identifikationsnummer senden';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_4b46caf217f7d78d19e8d78aafda3095'] = 'Sendet eine E-Mail an Kunden mit leerer Umsatzsteuer-Identifikationsnummer, wenn das Feld erforderlich ist.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_4665455c0d21839c3b1e73424948f92c'] = 'E-Mail für doppelte Umsatzsteuer-Identifikationsnummer senden';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_65ca5906354fc72ec51b9919275815eb'] = 'Sendet eine E-Mail an Kunden mit doppelter Umsatzsteuer-Identifikationsnummer, wenn eine doppelte Umsatzsteuer-Identifikationsnummer nicht zulässig ist.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_a563e3bee93a3d4e7eb9c79e787d00c6'] = 'Kundengruppenzuordnung';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_afa4d6b888533ffb7b46f75229bbb0a6'] = 'Verwaltet Client-Gruppen wie im Abschnitt [Client Group Assignment] konfiguriert.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_63c7f394d26cf6c99782073393b16e59'] = 'E-Mail für ungültigen Firmennamen senden';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_9916805045ddbc816ee2ee9dcb213f87'] = 'Sendet E-Mail an Kunden mit gültiger Umsatzsteuer-Identifikationsnummer, aber Firmenname, der nicht in VIES oder GOV.UK registriert ist.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_8e6221f7d0f5c7785644c20a4fb810c2'] = 'E-Mail für leeren Firmennamen senden';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_fd77c779bce84eaa4fa0c5b782d68407'] = 'Sendet eine E-Mail an Kunden mit gültiger Umsatzsteuer-Identifikationsnummer, aber leerem Firmennamen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_566e2ff5dbf23e8556ea63fda04a947e'] = 'Registrierten Firmennamen automatisch einfügen';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_0f11441c8ca95dbcee2dffae877c71f5'] = 'Das System fügt den registrierten Firmennamen in VIES oder GOV.UK für Kunden ein, die eine gültige Umsatzsteuer-Identifikationsnummer haben.';
$_MODULE['<{advancedvatmanager}prestashop>advancedvatmanager_2e6fdff6558e75b8cbc9971155e7b97d'] = 'Diese Aktion überschreibt den Firmennamen, den der Kunde bereits in der Adresse gespeichert hat, und ersetzt ihn durch den Firmennamen, der bei VIES oder GOV.UK registriert ist.';
